func novelSuggestedKeep(members []novelDedupeMember) novelDedupeMember {
	best := members[0]
	for _, m := range members[1:] {
		if m.ReadingProgress > best.ReadingProgress || (m.ReadingProgress == best.ReadingProgress && m.NumHighlights > best.NumHighlights) || (m.ReadingProgress == best.ReadingProgress && m.NumHighlights == best.NumHighlights && novelKeepURLLess(m, best)) {
			best = m
		}
	}
	return best
}

func novelDedupeClusters(members []novelDedupeMember, by map[string]bool) []novelDedupeCluster {
	groups := map[string][]novelDedupeMember{}
	for _, m := range members {
		if by["url"] {
			if key := novelNormalizeURL(m.URL); key != "" {
				groups["url:"+key] = append(groups["url:"+key], m)
			}
		}
		if by["title"] {
			if key := novelNormalizeTitle(m.Title); novelValidDedupeTitleKey(key) {
				authorKey := novelNormalizeTitle(m.Author)
				if authorKey != "" {
					groups["title:"+key+"\x00"+authorKey] = append(groups["title:"+key+"\x00"+authorKey], m)
				}
			}
		}
	}
	clusters := make([]novelDedupeCluster, 0)
	for key, ms := range groups {
		if len(ms) < 2 {
			continue
		}
		parts := strings.SplitN(key, ":", 2)
		confidence := "medium"
		displayKey := parts[1]
		if parts[0] == "url" {
			confidence = "high"
		} else {
			keyParts := strings.SplitN(parts[1], "\x00", 2)
			displayKey = keyParts[0]
			if novelDedupeHasSharedURL(ms) {
				continue
			}
		}
		clusters = append(clusters, novelDedupeCluster{
			Key:           displayKey,
			By:            parts[0],
			Confidence:    confidence,
			Members:       ms,
			SuggestedKeep: novelSuggestedKeep(ms),
		})
	}
	sort.Slice(clusters, func(i, j int) bool {
		if clusters[i].By == clusters[j].By {
			return clusters[i].Key < clusters[j].Key
		}
		return clusters[i].By < clusters[j].By
	})
	return clusters
}

func novelDedupeHasSharedURL(members []novelDedupeMember) bool {
	seen := map[string]bool{}
	for _, member := range members {
		key := novelNormalizeURL(member.URL)
		if key == "" {
			continue
		}
		if seen[key] {
			return true
		}
		seen[key] = true
	}
	return false
}

func novelLoadDedupeMembers(cmd *cobra.Command, scope map[string]bool) ([]novelDedupeMember, bool, error) {
	exists, err := novelLocalStoreExists(cmd)
	if err != nil {
		return nil, false, err
	}
	if !exists {
		return []novelDedupeMember{}, true, nil
	}
	db, err := novelOpenStore(cmd)
	if err != nil {
		return nil, false, err
	}
	defer db.Close()
	members := make([]novelDedupeMember, 0)
	totalRows := 0
	if scope["docs"] || scope["documents"] {
		rows, err := db.DB().Query(`SELECT id, title, author, COALESCE(NULLIF(source_url,''), url), reading_progress, saved_at
			FROM documents WHERE COALESCE(parent_id, '') = ''`)
		if err != nil {
			return nil, false, err
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			var title, author, rawURL, saved sql.NullString
			var progress sql.NullFloat64
			if err := rows.Scan(&id, &title, &author, &rawURL, &progress, &saved); err != nil {
				return nil, false, err
			}
			totalRows++
			members = append(members, novelDedupeMember{Kind: "doc", SavedAt: novelParseTime(saved.String), ID: id, Title: cliutil.CleanText(title.String), Author: cliutil.CleanText(author.String), URL: rawURL.String, ReadingProgress: func() float64 {
				if progress.Valid {
					return progress.Float64
				}
				return 0
			}()})
		}
		if err := rows.Err(); err != nil {
			return nil, false, err
		}
	}
	if scope["books"] {
		rows, err := db.DB().Query(`SELECT id, title, author, source_url, num_highlights, COALESCE(json_extract(data, '$.saved_at'), json_extract(data, '$.created_at'), last_highlight_at, updated) FROM books`)
		if err != nil {
			return nil, false, err
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			var title, author, rawURL, saved sql.NullString
			var highlights sql.NullInt64
			if err := rows.Scan(&id, &title, &author, &rawURL, &highlights, &saved); err != nil {
				return nil, false, err
			}
			totalRows++
			members = append(members, novelDedupeMember{Kind: "book", SavedAt: novelParseTime(saved.String), ID: id, Title: cliutil.CleanText(title.String), Author: cliutil.CleanText(author.String), URL: rawURL.String, NumHighlights: highlights.Int64})
		}
		if err := rows.Err(); err != nil {
			return nil, false, err
		}
	}
	return members, totalRows == 0, nil
}

