func novelKeepURLLess(a, b novelDedupeMember) bool {
	aq, bq := strings.Contains(a.URL, "?"), strings.Contains(b.URL, "?")
	if aq != bq {
		return !aq
	}
	al, bl := len(novelNormalizeURL(a.URL)), len(novelNormalizeURL(b.URL))
	if al != bl {
		return al < bl
	}
	if !a.SavedAt.Equal(b.SavedAt) {
		if a.SavedAt.IsZero() {
			return false
		}
		if b.SavedAt.IsZero() {
			return true
		}
		return a.SavedAt.Before(b.SavedAt)
	}
	return a.ID < b.ID
}
